import numpy as np
from builder import build, write_xyz

cov = {'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Se':1.20,'Re':1.5}
def clashes(at):
    out = []
    for i in range(len(at)):
        for j in range(i+1, len(at)):
            d = np.linalg.norm(at[i][1]-at[j][1])
            if d < 0.75*(cov[at[i][0]]+cov[at[j][0]]):
                out.append((round(d,2), i, j, at[i][0], at[j][0]))
    return out

def minnonbonded(at):
    m = 9e9; pair=None
    for i in range(len(at)):
        for j in range(i+1, len(at)):
            d = np.linalg.norm(at[i][1]-at[j][1])
            r = d/(cov[at[i][0]]+cov[at[j][0]])
            if r >= 0.8 and r < m:
                m = r; pair=(i,j,at[i][0],at[j][0],round(d,2))
    return m, pair

best = None
for phi_ax in (0,30,60,90,120,150):
    for phi_B in (0,30,60,90,120,150):
        for phi_C in (0,30,60,90,120,150):
            for prop in (30,60,90):
                at = build(phi_ax=phi_ax, phi_B=phi_B, phi_C=phi_C, prop=prop)
                if clashes(at): continue
                m, pair = minnonbonded(at)
                if best is None or m > best[0]:
                    best = (m, phi_ax, phi_B, phi_C, prop, pair)
print("best:", best)
m, phi_ax, phi_B, phi_C, prop, pair = best
at = build(phi_ax=phi_ax, phi_B=phi_B, phi_C=phi_C, prop=prop)
write_xyz(at, 'initial.xyz')
print("wrote initial.xyz with", len(at), "atoms; closest nonbonded:", pair)
